import django.db.models.deletion
from django.db import migrations, models


def copiar_categoria_de_cotizacion(apps, schema_editor):
    """Rellena la categoría de las líneas de muestra existentes con la de su
    cotización, con el mismo criterio que se usaba al leerla (nombre + color)."""
    PedidoDetalle = apps.get_model("ventas", "PedidoDetalle")
    CotizacionDetalle = apps.get_model("ventas", "CotizacionDetalle")
    categorias = {}
    for cd in CotizacionDetalle.objects.filter(
        producto__isnull=True, categoria_producto__isnull=False
    ).values("cotizacion_id", "producto_nombre_externo", "color_id", "categoria_producto_id").order_by("id"):
        categorias.setdefault((cd["cotizacion_id"], cd["producto_nombre_externo"]), {})[cd["color_id"]] = (
            cd["categoria_producto_id"]
        )
    for det in PedidoDetalle.objects.filter(
        producto__isnull=True, categoria_producto__isnull=True, pedido__cotizacion__isnull=False
    ).values("id", "pedido__cotizacion_id", "producto_nombre_externo", "color_id"):
        por_color = categorias.get((det["pedido__cotizacion_id"], det["producto_nombre_externo"]), {})
        categoria_id = por_color.get(det["color_id"]) or por_color.get(None) or next(iter(por_color.values()), None)
        if categoria_id:
            PedidoDetalle.objects.filter(pk=det["id"]).update(categoria_producto_id=categoria_id)


